def _ledger(revision_priority, tax_base, refunds):
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            if revision_priority == "sequence_first":
                rank = (sequence, event.get("revision", 0), position)
            else:
                rank = (event.get("revision", 0), position)
            if event_id not in chosen or rank > chosen[event_id][0]:
                chosen[event_id] = (rank, event)

        balances = dict(data.get("opening", {}))
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            base = raw if tax_base == "original" else net
            tax = rounded(base * event.get("tax_bp", 0), 10000, data["rounding"])
            total = net + tax
            if refunds and event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    options = {}
    for name in names:
        allowed = [version for version in rows[name]
                   if version not in blocked.get(name, [])
                   and (name not in pins or pins[name] == version)]
        options[name] = [None] + allowed

    assignment = {}
    best_vector = None
    best_result = None

    def feasible():
        installed = {name for name, version in assignment.items() if version is not None}
        for name, (low, high) in roots.items():
            if name not in installed or not low <= assignment[name] <= high:
                return False

        edges = {name: [] for name in installed}
        reachable = set()
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name in reachable:
                continue
            if name not in installed:
                return False
            reachable.add(name)
            row = rows[name][assignment[name]]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                if (other not in installed or
                        not dep["min"] <= assignment[other] <= dep["max"]):
                    return False
                edges[name].append(other)
                pending.append(other)
        if reachable != installed:
            return False

        state = {}

        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not visit(other) for other in edges[name]):
                return False
            state[name] = 2
            return True

        return all(visit(name) for name in installed)

    def search(index):
        nonlocal best_vector, best_result
        if index == len(names):
            if feasible():
                vector = tuple(-1 if assignment[name] is None else assignment[name]
                               for name in names)
                if best_vector is None or vector > best_vector:
                    best_vector = vector
                    best_result = {name: assignment[name] for name in names
                                   if assignment[name] is not None}
            return
        name = names[index]
        for version in options[name]:
            assignment[name] = version
            search(index + 1)
        del assignment[name]

    search(0)
    if best_result is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_result}


def _jobs(data):
    from itertools import combinations

    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    if len(mandatory) > k or not mandatory.issubset({job["id"] for job in jobs}):
        return {"error": "impossible"}

    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for selected in combinations(jobs, k):
        ids = [job["id"] for job in selected]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        if any(sum(other["start"] <= time < other["end"] for other in selected) > 2
               for time in (job["start"] for job in selected)):
            continue

        sorted_ids = sorted(ids)
        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    import heapq

    required = data.get("required", [])
    bits = {node: 1 << index for index, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bits.get(source, 0)
    coupons = data["coupons"]
    start_state = (source, initial_mask, coupons)
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, coupons)]

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], remaining)]
            if remaining:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, remaining - 1))
            for duration, left in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, left))

    return {"arrival": None}


